<script setup lang="ts">import{ref}from"vue";import{applyChannelBatch,type BatchAction}from"@/domain/iptv/batchActions";import type{IptvCategoryRecord,IptvChannelRecord,NamedRecord}from"@/types/records";const props=defineProps<{channels:IptvChannelRecord[];categories:IptvCategoryRecord[];countries:NamedRecord[]}>();const emit=defineEmits<{completed:[IptvChannelRecord[],string[]];clear:[]}>();const running=ref(false),progress=ref(0),action=ref<BatchAction>("activate"),value=ref(""),error=ref("");async function run(){if(!props.channels.length)return;if(action.value==="archive"&&!confirm(`Arquivar ${props.channels.length} canais?`))return;running.value=true;error.value="";const r=await applyChannelBatch(props.channels,action.value,value.value,(done)=>progress.value=done);emit("completed",r.updated,r.failed.map(x=>`${x.channel.nome}: ${x.message}`));if(r.failed.length)error.value=`${r.failed.length} operações falharam.`;running.value=false}</script><template><section class="iptv-bulk panel" aria-labelledby="bulk-title"><div><h3 id="bulk-title">{{channels.length}} canais selecionados</h3><p v-if="running" aria-live="polite">A processar {{progress}} de {{channels.length}}.</p><p v-if="error" class="field-error" role="alert">{{error}}</p></div><select v-model="action" :disabled="running"><option value="activate">Ativar</option><option value="deactivate">Desativar</option><option value="favorite">Marcar favorito</option><option value="unfavorite">Desmarcar favorito</option><option value="category">Alterar categoria</option><option value="country">Alterar país</option><option value="archive">Arquivar</option></select><select v-if="action==='category'" v-model="value" :disabled="running"><option value="">Sem categoria</option><option v-for="x in categories" :key="x.id" :value="x.id">{{x.nome}}</option></select><select v-if="action==='country'" v-model="value" :disabled="running"><option value="">Sem país</option><option v-for="x in countries" :key="x.id" :value="x.id">{{x.nome||x.codigo}}</option></select><button class="button button-primary" type="button" :disabled="running" @click="run">Aplicar</button><button class="button button-secondary" type="button" :disabled="running" @click="emit('clear')">Limpar seleção</button></section></template>
